-- ============================================================
-- wz 名称映射表（由 String.wz 自动生成，共 27238 条）
-- 用途：把 drop_data / shopitems 等表里的裸 ID 翻译成中文名
-- 导入：mysql -uzhoubw -p heavenms < wz_name_tables.sql
-- 注意：这是只读参考表，服务端不会读取它，纯属方便你查数据
-- ============================================================

DROP TABLE IF EXISTS `wz_names`;
CREATE TABLE `wz_names` (
  `kind` VARCHAR(16) NOT NULL COMMENT '类别: mob/eqp/consume/etc/ins/cash/map/npc/pet',
  `id`   INT(11)     NOT NULL COMMENT 'ID',
  `name` VARCHAR(160) NOT NULL COMMENT '中文名',
  PRIMARY KEY (`kind`,`id`),
  KEY `idx_id` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='wz 名称映射（只读参考）';


-- ------------------------------------------------------------
-- 建一个「物品名」视图（装备/消耗/其他/椅子/点券 合并）
-- ------------------------------------------------------------
CREATE OR REPLACE VIEW `v_item_name` AS
SELECT `id`, `name`, `kind` FROM `wz_names` WHERE `kind` IN ('eqp','consume','etc','ins','cash');

-- ============================================================
-- 现成查询（复制到 MySQL Workbench 里改改就能用）
-- ============================================================

-- 【1】蜗牛(100100)掉什么，掉率多少
--     chance 是百万分比，/10000 就是百分比
SELECT d.dropperid,
       COALESCE(m.name,'?') AS 怪物,
       IF(d.itemid=0,'金币',COALESCE(i.name,'?')) AS 掉落物,
       d.itemid, d.chance,
       ROUND(d.chance/10000, 4) AS 百分比,
       d.minimum_quantity AS 最少, d.maximum_quantity AS 最多, d.questid
FROM drop_data d
LEFT JOIN wz_names m ON m.kind='mob' AND m.id=d.dropperid
LEFT JOIN v_item_name i ON i.id=d.itemid
WHERE d.dropperid=100100 ORDER BY d.chance DESC;

-- 【2】全库掉率最高的 50 件东西（找异常配置用）
SELECT d.dropperid, m.name AS 怪物, i.name AS 掉落物, d.itemid, d.chance,
       ROUND(d.chance/10000,3) AS 百分比
FROM drop_data d
LEFT JOIN wz_names m ON m.kind='mob' AND m.id=d.dropperid
LEFT JOIN v_item_name i ON i.id=d.itemid
ORDER BY d.chance DESC LIMIT 50;

-- 【3】某个物品从哪些怪身上掉（比如 4000019 绿色蜗牛壳）
SELECT d.itemid, i.name AS 物品, d.dropperid, m.name AS 来源怪物,
       d.chance, ROUND(d.chance/10000,3) AS 百分比
FROM drop_data d
LEFT JOIN wz_names m ON m.kind='mob' AND m.id=d.dropperid
LEFT JOIN v_item_name i ON i.id=d.itemid
WHERE d.itemid=4000019 ORDER BY d.chance DESC;

-- 【4】哪个怪的掉率配置条数最多
SELECT d.dropperid, m.name AS 怪物, COUNT(*) AS 掉落条数
FROM drop_data d LEFT JOIN wz_names m ON m.kind='mob' AND m.id=d.dropperid
GROUP BY d.dropperid ORDER BY 掉落条数 DESC LIMIT 20;

-- 【5】全局掉落表翻译
SELECT g.continent,
       IF(g.itemid=0,'金币',COALESCE(i.name,'?')) AS 掉落物,
       g.itemid, g.chance, ROUND(g.chance/10000,3) AS 百分比, g.comments
FROM drop_data_global g LEFT JOIN v_item_name i ON i.id=g.itemid;

-- 【6】只有 ID 想查名字时
SELECT * FROM wz_names WHERE kind='mob' AND id=1110100;      -- 怪物
SELECT * FROM v_item_name WHERE id=2000000;                  -- 物品
SELECT * FROM wz_names WHERE name LIKE '%蜗牛%';             -- 反查 ID
